#include "crimsonland_gameplay.h"

struct queue_vec { float x,y; };
struct queue_color { float r,g,b,a; };

extern "C" unsigned char fx_queue_add(
    int effect_id,
    vec2f_t *pos,
    float width,
    float height,
    float rotation,
    effect_color_t *color)
{
    int count = fx_queue_count;
    int offset = count * sizeof(fx_queue_entry_t);
    ++count;
    fx_queue_entry_t *entry = (fx_queue_entry_t *)((char *)fx_queue + offset);

    *(queue_vec *)&entry->position = *(queue_vec *)pos;
    entry->color = *color;
    entry->width = width;
    entry->height = height;
    entry->rotation = rotation;
    entry->effect_id = effect_id;
    fx_queue_count = count;

    if (count >= 0x80) {
        fx_queue_count = 0x7f;
        return 0;
    }
    return 1;
}

